class CursorPage(TypedDict, Generic[T]):
    """A page of a cursor-paginated list.

    Pass ``next_cursor`` back as the cursor query parameter to read the next
    page; it is ``None`` on the last page.
    """

    data: list[T]
    # Base path for paginator generated URLs.
    path: str | None
    # Number of items shown per page.
    per_page: int
    # The "cursor" that points to the next set of items.
    next_cursor: str | None
    next_page_url: str | None
    # The "cursor" that points to the previous set of items.
    prev_cursor: str | None
    prev_page_url: str | None


